	PRIVATE_PRESENCE_LAPSED = "La presenza privata è disattivata: questo personaggio non è più il Re, né nell'Alto Consiglio firmato, né l'autore dell'addon.",
	PRIVATE_PRESENCE_OFF = "La presenza privata è disattivata. Olympus può annunciarti di nuovo; la tua posizione resta privata finché non sei tu a condividerla.",
	PRIVATE_PRESENCE_ON = "La presenza privata è attiva, e resta attiva tra un login e l'altro finché non la disattivi. Olympus ha ritirato la posizione che condividevi e non ti annuncia più online né dice dove sei. Viene avvisata solo la tua gilda, così i client Olympus dei suoi membri ti contano offline nel censimento che inviano (un Olympus più vecchio potrebbe non farlo). L'elenco Blizzard della tua gilda, /who e le righe di chat che scrivi ti mostrano comunque.",
	PRIVATE_PRESENCE_ONLY = "Solo il Re attuale, l'Alto Consiglio firmato o l'autore dell'addon possono usare la presenza privata.",
	PRIVATE_PRESENCE_OTHER_OWNER = "La presenza privata è gestita da un'integrazione autorizzata. Disattivala lì; Olympus non scavalcherà la sua scelta sulla privacy.",
	PROFILE_ARENA_HISTORY = "Cronologia",
	PROFILE_EDIT_BTN = "Modifica il mio profilo",
	PROFILE_FIELD_HEARD = "Ultima ricezione %s",
	PROFILE_FIELD_META = "%s · %s",
	PROFILE_FRAME_NONE = "Nessuna cornice",
	PROFILE_FRAME_RANK = "La cornice del mio grado",
