	PROFILE_HONOURS = "I tuoi onori",
	PROFILE_ICON_REFUSED = "Quell'icona non può essere usata qui: scegli uno dei segni dei tuoi onori (o, per il tuo emblema, una delle icone del gioco).",
	PROFILE_LOCK = "Mantieni la mia scelta",
	PROFILE_LOCKED = "Scelta mantenuta",
	PROFILE_NO_HONOURS = "Ancora nessuno: cinture, podi, donazioni, la corsa ai livelli, l'Oracolo, la miglior gilda.",
	PROFILE_SOURCE_ADDON = "stato dell'addon",
	PROFILE_SOURCE_DERIVED = "derivato",
