	PROFILE_SOURCE_PROFILE = "profilo condiviso",
	PROFILE_SOURCE_REPORT = "censimento della gilda",
	PROFILE_SOURCE_ROSTER = "elenco della gilda",
	PROFILE_SOURCE_SIGNED = "autorità firmata",
	PROFILE_SOURCE_UNKNOWN = "fonte sconosciuta",
	PROFILE_SOURCE_WHO = "/who",
	PROFILE_TITLE_NONE = "Nessun titolo",
	PROFILE_VISIBILITY_BTN = "Visibilità del profilo e fonti",
	PUBLIC_NET = "Canale pubblico: chiunque entri in %s può leggere il censimento e le chat di Olympus.",
	PUBLIC_NET_OFFICER = "Ufficiali: sigillalo con la chiave usata dalle altre gilde (/oly key).",
	PUBLIC_NET_SPLIT = "%d compagni di gilda sono sul canale sigillato: un ufficiale online ti passa la chiave.",
	PUBLIC_NET_TIP = "Non è impostata alcuna chiave di reame, quindi ogni addon di Olympus si incontra sul canale pubblico %s. Chiunque può entrarci per nome e, con uno script di una riga, leggere tutto ciò che vi viene inviato: il censimento, dove si trovano le persone (per chi lo condivide), le tre chat (anche [Capitani] e [Signori]) e i decreti. Sigillato con una chiave, il nome e la password del canale derivano dalla chiave e solo i giocatori che la possiedono possono entrare. Un ufficiale scrive /oly key <secret> una volta, e i compagni di gilda con l'addon ricevono la chiave da soli tramite la chat di gilda. Usa il segreto che usano gli ufficiali delle altre gilde: una chiave tutta tua separa la tua gilda dall'esercito.",
	PUBLIC_NET_TITLE = "Il canale di Olympus è pubblico",
	PUBLISHED_BY = "da %s, %s",
	QUIET_PRESENCE_HELD = "La presenza discreta è attiva: Olympus lo invia quando sarà disattivata.",
	QUIET_PRESENCE_LINE = "Presenza discreta: Olympus smette di annunciarti e di dire dove sei. L'elenco della tua gilda, il censimento che i tuoi compagni ne ricavano, /who e la chat ti mostrano comunque.",
	QUIET_PRESENCE_TIP = "Hai attivato la Presenza privata, oppure un addon che hai autorizzato ha attivato una presenza discreta. Olympus smette di inviare, di sua iniziativa, le parole che ti annunciano online o dicono dove sei: niente saluto, rapporto del censimento, layer, punto sulla mappa, offerta di salto di layer, corte, avvisi di donazioni o di servizio, risposte di aiuto o da artigiano, avvistamenti dei Ricercati o risposte agli avvistamenti, presentazione del profilo, né la corona del Re o le liste che il suo client ripete. Ciò che gli altri client hanno sentito prima scade come dopo un logout. Il censimento dei tuoi compagni di gilda legge comunque l'elenco della gilda: un capo o un ufficiale di gilda compare ancora online lì, e la tua zona può comparire per un massimo di 12 minuti. Con la Presenza privata viene avvisata la tua gilda, e i client Olympus dei suoi membri ti contano offline nel censimento che inviano (un Olympus più vecchio potrebbe non farlo). Le righe di chat di Olympus che scrivi, ciò che pubblichi tu stesso e i registri che il tuo client inoltra vengono comunque inviati. La Presenza privata resta attiva tra un login e l'altro finché non la disattivi. La presenza discreta di un addon finisce quando quell'addon la disattiva, con un /reload o al logout; dopo un /reload, Olympus potrebbe salutare prima che quell'addon la riattivi.",
	RANKS = "Gradi",
	RANK_RULES_BACK = "< Indietro",
	RANK_RULES_EVIDENCE = "Prove",
	RANK_RULES_LIMITS = "Limiti di conteggio",
	RANK_RULES_LINK = "Regole delle classifiche",
	RANK_RULES_LINK_TIP = "Apri in questa finestra le regole di punteggio, ordinamento, prove e visibilità.",
	RANK_RULES_NOTE = "Come viene calcolata questa classifica dai registri conservati da questo client. Le prove mancanti restano sconosciute.",
	RANK_RULES_ORDER = "Ordine e pareggi",
	RANK_RULES_SCORE = "Punteggio",
	RANK_RULES_VISIBILITY = "Chi può vederla",
	RANK_RULE_ARENA_EVIDENCE = "La classifica viene ricostruita dai registri conservati dei combattimenti valutati. Un registro mancante o rifiutato non crea un risultato.",
	RANK_RULE_ARENA_LIMITS = "Un combattimento valutato richiede in media almeno %d secondi per round. Contano al massimo %d combattimenti per giocatore per giorno del server e %d combattimenti contro lo stesso avversario in %d giorni. Le prove generali e i combattimenti non confermati non contano.",
	RANK_RULE_ARENA_ORDER = "Le posizioni di sempre usano il punteggio più alto, poi più combattimenti valutati, poi il nome; punteggi uguali condividono un posto. Le viste per periodo usano il punteggio guadagnato, le vittorie, meno sconfitte, il punteggio attuale, poi il nome.",
	RANK_RULE_ARENA_REPEAT = "I combattimenti ripetuti tra la stessa coppia entro %d ore contano progressivamente 1, 1/2, 1/4 e così via.",
	RANK_RULE_ARENA_SCORE = "Un combattente senza punteggio pregresso parte da %d. Tra una stagione e l'altra, un punteggio conservato torna a metà strada verso %d. K=%d si applica solo finché il combattente non è stabilizzato e ha meno di %d combattimenti valutati; un combattente stabilizzato può quindi partire fuori da %d e usa K=%d, o K=%d dal punteggio %d. Ogni livello di differenza conta come %d punti di punteggio; lo scarto totale del punteggio atteso è limitato a %d.",
	RANK_RULE_ARENA_TITLE = "Punteggio dell'Arena",
	RANK_RULE_ARENA_VISIBILITY = "Lo staff dei giochi la vede sempre. I membri la vedono solo mentre l'interruttore Arena di un pubblicatore autorizzato è aperto.",
	RANK_RULE_BONES_EVIDENCE = "Contano solo le metà di partita firmate e corrispondenti conservate da questo client. Le metà mancanti restano sconosciute.",
	RANK_RULE_BONES_LIMITS = "Una partita richiede almeno %d secondi. Contano al massimo %d partite per giocatore per giorno del server e %d partite contro lo stesso avversario in %d giorni.",
	RANK_RULE_BONES_ORDER = "Prima chi ha più vittorie; i pareggi usano meno partite, poi il momento più vicino in cui è stato raggiunto quel totale di vittorie, poi il nome. Il campione e il podio del mese precedente chiuso vengono conservati a parte.",
	RANK_RULE_BONES_SCORE = "Il mese di calendario corrente classifica le vittorie confermate tra giocatori. Pratica, partite contro il banco, alt dello stesso proprietario, giocatori nascosti e registri le cui due metà firmate non concordano non contano.",
	RANK_RULE_BONES_TITLE = "Classifica del Lancio delle Ossa",
	RANK_RULE_BONES_VISIBILITY = "Lo staff dei giochi la vede sempre. I membri la vedono solo mentre l'interruttore Lancio delle Ossa di un pubblicatore autorizzato è aperto.",
	RANK_RULE_CHURCH_EVIDENCE = "Contano solo i registri confermati di reclute e di permanenza successiva conservati nei libri della Chiesa. I registri mancanti sono sconosciuti e non creano punti.",
	RANK_RULE_CHURCH_FULLNESS_ORDER = "Prima chi ha più giorni validi completati. I pareggi usano la media più alta delle medie giornaliere valide, poi il nome della gilda.",
	RANK_RULE_CHURCH_FULLNESS_TITLE = "Classifica di pienezza delle gilde",
	RANK_RULE_CHURCH_FULLNESS_VISIBILITY = "È riservata al pubblico della Chiesa; non fa parte della classifica pubblica della Chiesa.",
	RANK_RULE_CHURCH_ORDER = "Prima il punteggio totale più alto; i pareggi usano più punti propri, poi il nome. Le finestre di una settimana, 30 giorni e di sempre contano solo le prove datate in quella finestra.",
	RANK_RULE_CHURCH_SCORE = "Una recluta confermata dà %d punti. Una recluta ancora in Olympus dopo %d giorni ne dà altri %d. Un capo riceve anche il %d%%, il %d%% e il %d%% dei punti propri guadagnati nei primi tre livelli sotto di lui; le quote non si cumulano.",
	RANK_RULE_CHURCH_TITLE = "Classifica del servizio alla Chiesa",
	RANK_RULE_CHURCH_VISIBILITY = "Il pubblico della Chiesa vede la classifica completa. La pagina pubblica mostra solo le righe di chi ha aderito mentre l'interruttore di pubblicazione autorizzato è aperto.",
	RANK_RULE_CRAFT_EVIDENCE = "Il richiedente e l'artigiano firmano la stessa richiesta completata. In caso di disaccordo si usa la rarità osservata più bassa; una dichiarazione unilaterale non entra mai nella classifica.",
	RANK_RULE_CRAFT_LIMITS = "Contano al massimo %d consegne al giorno tra lo stesso richiedente e lo stesso artigiano, e nessun giocatore può aggiungere più di %d registri di creazione in un giorno.",
	RANK_RULE_CRAFT_ORDER = "Prima chi ha più punti, poi più clienti diversi, poi più consegne, poi il nome del personaggio.",
	RANK_RULE_CRAFT_SCORE = "Una consegna confermata parte da 10 punti. Quantità maggiori aggiungono un bonus limitato e sublineare; i risultati non comuni, rari, epici e leggendari aggiungono punti di rarità crescenti. Conoscere solo una ricetta non dà punti.",
	RANK_RULE_CRAFT_TITLE = "Classifica del servizio di creazione",
	RANK_RULE_CRAFT_VISIBILITY = "Il registro firmato viene conservato e inoltrato dai client che lo possiedono, quindi la classifica globale mensile non richiede che nessuno dei due giocatori originali resti online.",
	RANK_RULE_DEBTORS_EVIDENCE = "Contano solo le voci confermate del registro delle commissioni conservate dallo sportello commissioni o nella sua ultima risposta privata. Le voci non confermate aspettano fuori dalla classifica.",
	RANK_RULE_DEBTORS_ORDER = "Prima chi ha più rame scaduto, poi più rame dovuto in totale, poi il nome. Il livello di riscossione cambia alla scadenza, dopo %d ore e dopo %d ore.",
	RANK_RULE_DEBTORS_SCORE = "Non è una classifica d'onore. Una commissione di gilda confermata scade %d ore dopo la vendita diretta completata. Le commissioni aperte sono raggruppate per artigiano, con il totale dovuto e gli importi già scaduti tenuti separati.",
	RANK_RULE_DEBTORS_TITLE = "Ordine di riscossione delle commissioni di creazione",
	RANK_RULE_DEBTORS_VISIBILITY = "Possono vederla solo i lettori privati esistenti del registro delle commissioni. Niente qui pubblica debiti o sposta oro automaticamente.",
	RANK_RULE_DONORS_DUES = "Quando il libro del Tesoriere è condiviso fuori dalla sua vista privata, la possibile parte delle quote settimanali viene rimossa. Gli altri libri dei custodi mostrano i doni validi come registrati.",
	RANK_RULE_DONORS_EVIDENCE = "Questo client classifica i libri che possiede al momento. Un libro mancante o più vecchio è una prova mancante o più vecchia, non zero.",
	RANK_RULE_DONORS_ORDER = "Prima più rame valido; i totali uguali sono ordinati per nome.",
	RANK_RULE_DONORS_SCORE = "I doni in entrata validi vengono sommati in rame. Le righe del registro restituite, in uscita, trasferite ed escluse non si aggiungono al totale.",
	RANK_RULE_DONORS_TITLE = "Classifica dei donatori",
	RANK_RULE_DONORS_VISIBILITY = "Possono vederla il Re, i suoi Siniscalchi e i custodi. Gli altri membri la vedono solo mentre l'interruttore della classifica del Re è aperto.",
	RANK_RULE_GUILD_TREASURY_EVIDENCE = "Ogni riga usa l'ultima istantanea autorizzata conservata qui. I prezzi degli oggetti in sospeso rendono il suo totale un importo 'almeno'. Le gilde mancanti e gli oggetti senza prezzo restano sconosciuti.",
	RANK_RULE_GUILD_TREASURY_ORDER = "Prima il totale più alto; i pareggi usano il livello medio noto più alto, poi il nome della gilda. La Tesoreria Federale è mostrata a parte e non occupa un posto.",
	RANK_RULE_GUILD_TREASURY_SCORE = "Il totale di ogni gilda è l'oro nella sua istantanea autorizzata della banca più il valore noto configurato o di vendita al mercante di ogni oggetto. Agli oggetti senza prezzo non viene inventato un valore.",
	RANK_RULE_GUILD_TREASURY_TITLE = "Classifica delle tesorerie di gilda",
	RANK_RULE_GUILD_TREASURY_VISIBILITY = "Solo il pubblico privato esistente della tesoreria di gilda può vedere questa classifica. Non viene pubblicata all'esercito.",
	RANK_RULE_LEVEL_EVIDENCE = "Sono incluse solo le liste dei personaggi migliori nei rapporti di gilda recenti conservati da questo client. È una vista locale del censimento, non una certificazione del server.",
	RANK_RULE_LEVEL_ORDER = "Prima il livello più alto; i livelli uguali sono ordinati per nome del personaggio. La pagina mostra al massimo %d personaggi, %d alla volta.",
	RANK_RULE_LEVEL_SCORE = "Non ci sono punti: i personaggi sono ordinati in base all'ultimo livello riportato.",
	RANK_RULE_LEVEL_TITLE = "Corsa ai livelli",
	RANK_RULE_LEVEL_VISIBILITY = "Ogni membro di Olympus può vedere la stessa pagina della classifica, costruita dai rapporti che il suo client ha sentito.",
	RANK_RULE_WANTED_BOUNTY = "Per le prove attuali con punteggio, una morte contata aggiunge il livello della vittima e il bonus della sua carica verificata più alta alla taglia aperta del giocatore dell'Orda: Re 100, Alto Consiglio 50, capogilda 30, Legato 20, altra carica 10, membro 0, fino a un limite della taglia aperta di %d. Una ripetizione attuale con punteggio entro %d minuti non aggiunge né taglia né un'altra uccisione contata. Le prove di compatibilità più vecchie senza campi di punteggio mantengono il comportamento precedente: aggiungono un'uccisione storica e fino a 1 punto di taglia sotto lo stesso limite; la protezione attuale dalle ripetizioni con punteggio non viene applicata.",
	RANK_RULE_WANTED_EVIDENCE = "Le bacheche locali usano le righe conservate da questo client e le righe verificate che i membri di Olympus gli hanno condiviso; non sono totali certificati dal server. Le prove mancanti restano sconosciute. I vecchi punteggi vengono ricalcolati solo dove i fatti conservati dimostrano il risultato; altrimenti il vecchio totale resta archiviato invece di essere inserito a caso nella classifica.",
	RANK_RULE_WANTED_LIMITS = "Per le prove attuali con punteggio, la base di livello conta al massimo una volta per lo stesso uccisore e bersaglio in %d minuti, e la vendetta al massimo una volta in %d ore. Morti e uccisioni nelle istanze non contano. Le voci dell'Orda con zero taglia e zero uccisioni restano fuori dalla lista visibile dei Ricercati.",
	RANK_RULE_WANTED_ORDER = "I Ricercati sono ordinati per taglia aperta attuale più alta, poi più uccisioni contate in totale, poi il nome. I Cacciatori mensili e di sempre sono ordinati per più punti, poi il momento più vicino in cui è stato raggiunto quel totale, poi l'identità stabile. Solo una top tre globale firmata controlla le cornici del Cacciatore.",
	RANK_RULE_WANTED_SLAYER = "Un'uccisione valida attuale con punteggio di un giocatore dell'Orda dà un punto base ogni %d livelli dell'Orda, arrotondato per eccesso, più l'intera taglia aperta e %d punti per una vendetta ammissibile. La vendetta deve rispondere alla morte di quello stesso giocatore entro %d giorni. Una rivendicazione di compatibilità più vecchia senza campi di punteggio paga solo la taglia aperta, senza base di livello né vendetta.",
	RANK_RULE_WANTED_TITLE = "Classifiche dei Ricercati e dei Cacciatori",
	RANK_RULE_WANTED_VISIBILITY = "I membri di Olympus possono leggere queste regole e i registri che il loro client conserva. Solo il Re, l'Alto Consiglio firmato e l'autore possono pubblicare la top tre globale firmata. Le righe di posizione e i segnalini sulla mappa rispettano anche i controlli separati di condivisione della posizione e di moderazione.",
	RB_APOSTLE_1 = "Ehi,\n\nOra sei uno dei Dodici Apostoli della Chiesa Missionaria di Olympus. Dodici. Non uno di più. È enorme.\n\nIl compito: portare nuovi giocatori in Olympus e costruire una rete di missionari che facciano lo stesso.\n\nCosa si vede: i tre migliori Apostoli degli ultimi 30 giorni portano la croce degli Apostoli, e la vedono tutti.",
	RB_APOSTLE_2 = "Cosa ottieni:\n- Fino a 12 missionari tuoi (scheda Chiesa, Nomina, oppure clic destro su un giocatore).\n- La scheda Chiesa: la classifica, i tuoi numeri, le persone.\n- La stanza degli Apostoli e le stanze della Chiesa nella Chat.\n- Mentre giochi, il tuo addon tiene il libro della Chiesa per tutti.\n\nUna regola: nomina persone che lo faranno davvero.",
	RB_APOSTLE_LAUNCH = "Ok, ascolta.\n\nSiamo live. Sei uno dei dodici Apostoli di tutto l'esercito. È enorme. Ora la Chiesa si guadagna il suo nome.\n\nStesso compito: portare nuovi giocatori in Olympus e formare missionari che facciano lo stesso.\n\n- Nomina missionari: fino a 12 a testa, nella scheda Chiesa (Nomina) o con un clic destro su un giocatore. Loro nominano i propri, fino a cinque livelli sotto di te. 5.000 in tutta la Chiesa, al massimo.\n- Punti: 10 per ogni giocatore nuovo in Olympus che entra tramite te, altri 5 se è ancora qui 7 giorni dopo. In più, di quello che portano i tuoi tre livelli sotto: il 25%, dal primo; il 10% al secondo; il 5% oltre, al terzo. Qualcuno sotto di te può fare più punti di te. Bene. Vuol dire che funziona.\n- Hai portato qualcuno invitato da un altro giocatore? Registralo: conta se entra in una gilda Olympus entro 14 giorni.\n- I tre migliori Apostoli degli ultimi 30 giorni portano la croce.\n- Qualcuno ha smesso di giocare? Rimuovilo. Le persone che ha nominato restano al loro posto.\n\nUna regola: solo veri giocatori nuovi. Alt e passaggi tra gilde Olympus non contano mai. I punti esistono solo nel gioco, mai in oro.\n\nTieni l'addon acceso mentre giochi. Tiene il libro della Chiesa. Andiamo!",
	RB_APOSTLE_LAUNCH_TITLE = "La Chiesa, al lancio",
	RB_APOSTLE_RED = "Sotto Il mio profilo > Aspetto c'è anche una croce rossa che vedi solo tu.",
	RB_APOSTLE_TITLE = "Apostolo",
	RB_BACK = "< Tutte le lettere d'incarico",
	RB_BTN_CHURCH = "Chiesa",
	RB_BTN_CRAFTERS = "Artigiani",
	RB_BTN_DECREES = "Decreti",
	RB_BTN_GUILD = "Scheda Gilda",
	RB_BTN_THRONE = "Il Trono",
	RB_BTN_TREASURY = "Tesoreria",
	RB_BTN_WAR = "Sala di guerra",
	RB_BTN_WATCH = "La Guardia",
	RB_CHURCHCORR = "Ehi,\n\nOra sei il corrispondente della Chiesa di <%s>. Rispondi al Capo della Chiesa. Cioè a me.\n\nIl compito: tenere piena la tua gilda.\n\nCosa si vede: nessuna nuova cornice.\n\nCosa ottieni:\n- La scheda Chiesa: la classifica, i tuoi numeri e le persone.\n- Registrare una recluta che hai portato, fino a 15 aperte alla volta. Conta per te se entra in una gilda Olympus entro 14 giorni ed è nuova in Olympus.\n- La stanza della Chiesa nella Chat.\n\nIl tuo punteggio in classifica sono i giorni di fila sopra i 950 membri, contati dalla tua nomina.\n\nUna regola: fai crescere la tua gilda, ma mai portando via gente da un'altra gilda Olympus.",
	RB_CHURCHCORR_TITLE = "Corrispondente della Chiesa",
	RB_CHURCH_LETTER_LINK = "La tua lettera del Re",
	RB_CHURCH_LETTER_TIP = "La lettera della tua carica: il compito, cosa si vede e cosa sblocca.",
	RB_CORR_ARTISANRY = "Ehi,\n\nOra sei il corrispondente dell'Artigianato di <%s>. Il migliore amico degli artigiani.\n\nIl compito: aiutare i tuoi compagni di gilda a trovare artigiani, e far arrivare richieste, materiali e forniture a chi ne ha bisogno.\n\nCosa si vede: lo scudo dell'Associazione dell'Artigianato sul tuo ritratto e accanto al tuo nome.\n\nCosa ottieni:\n- La Bacheca degli artigiani, a un clic dalla tua scheda Gilda.\n- La stanza dell'Associazione dell'Artigianato e la stanza «Capogilda e Corrispondenti».\n\nGli strumenti del dipartimento non ci sono ancora. Per ora sei tu la persona a cui si chiede.\n\nUna regola: nessuno nella tua gilda resta bloccato senza un artigiano.",
	RB_CORR_ARTISANRY_TITLE = "Corrispondente dell'Artigianato",
	RB_CORR_CHURCHDEPT = "Ehi,\n\nOra sei il corrispondente di <%s> per la Chiesa Missionaria.\n\nIl compito: portare dentro nuovi giocatori e aiutare a tenere piena la tua gilda.\n\nCosa si vede: lo scudo della Chiesa Missionaria sul tuo ritratto e accanto al tuo nome.\n\nCosa ottieni: il titolo e la stanza del dipartimento. Sinceramente, è tutto qui. Dice a tutti chi è il contatto della tua gilda per la Chiesa.\n\nPer la stanza della Chiesa vera e propria e i numeri del reclutamento ti serve anche un posto nella Chiesa. Il tuo capogilda nomina il corrispondente della Chiesa nella scheda Chiesa, oppure un Apostolo ti nomina missionario.\n\nUna regola: porta dentro veri giocatori nuovi. Alt e passaggi tra gilde Olympus non contano mai.",
	RB_CORR_CHURCHDEPT_TITLE = "Corrispondente della Chiesa Missionaria",
	RB_CORR_HERALDRY = "Ok,\n\nOra sei il corrispondente dell'Araldica di <%s>. Sei la voce della tua gilda.\n\nIl compito: gestire i decreti, l'Agenda e le adunate della tua gilda, e far sì che la gente si presenti a eventi e live.\n\nCosa si vede: lo scudo del Dipartimento di Araldica sul tuo ritratto e accanto al tuo nome.\n\nCosa ottieni:\n- Ogni decreto per la tua gilda: Chiamate alle armi, Adunate, decreti reali, Ispezioni delle tabarde.\n- L'Agenda della tua gilda.\n- La stanza del Dipartimento di Araldica e la stanza «Capogilda e Corrispondenti».\n\nSolo la tua gilda. L'intero esercito spetta alla Corona e all'Alto Consiglio.\n\nUna regola: non gridare al lupo. Chiama quando conta.",
	RB_CORR_HERALDRY_TITLE = "Corrispondente dell'Araldica",
	RB_CORR_JUSTICE = "Ehi,\n\nOra sei il corrispondente di Giustizia di <%s>. Mantieni la pace.\n\nIl compito: sorvegliare la chat della tua gilda, gestire i problemi e lavorare con il tuo capogilda e il Consiglio di Giustizia.\n\nCosa si vede: lo scudo del Consiglio di Giustizia sul tuo ritratto e accanto al tuo nome.\n\nCosa ottieni:\n- L'intero banco della Guardia (scheda La Guardia) per i membri della tua gilda sotto di te: avvertimenti, timeout, la lista di sorveglianza, le segnalazioni.\n- Quando confermo un caso dopo il voto dell'Alto Consiglio, sei tu ad applicarlo nella tua gilda. L'addon non espelle mai nessuno da solo.\n- La stanza del Consiglio di Giustizia.\n\nUna regola: sii giusto. Stesse regole anche per i tuoi amici.",
	RB_CORR_JUSTICE_TITLE = "Corrispondente di Giustizia",
	RB_CORR_TREASURY = "Ehi,\n\nOra sei il corrispondente della Tesoreria di <%s>. Bello.\n\nIl compito: tenere in ordine i registri della Tesoreria della tua gilda e la condivisione della banca, con il tuo capogilda e la Tesoreria Federale.\n\nCosa si vede: lo scudo della Tesoreria Federale sul tuo ritratto e accanto al tuo nome.\n\nCosa ottieni:\n- La banca della tua gilda nell'addon. Apri la banca di gilda con l'addon attivo e lui scatta un'istantanea. Non sposta mai niente. Il tuo capogilda decide se la vede tutta la gilda.\n- La stanza della Tesoreria Federale e la stanza «Capogilda e Corrispondenti».\n\nUna regola: l'oro della gilda è della gilda. Tieni i conti puliti.",
	RB_CORR_TREASURY_TITLE = "Corrispondente della Tesoreria",
	RB_CORR_WAR = "Ok,\n\nOra sei il corrispondente della Guerra di <%s>. Sei quello che fa succedere le incursioni.\n\nIl compito: organizzare le incursioni e le operazioni PvP della tua gilda, i suoi gruppi d'incursione e i resoconti post-azione.\n\nCosa si vede: lo scudo del Dipartimento della Guerra sul tuo ritratto e accanto al tuo nome.\n\nCosa ottieni:\n- I diritti da ufficiale nella Sala di guerra della tua gilda (scheda Il Reame): operazioni, gruppi d'incursione, incarichi, resoconti post-azione.\n- La stanza del Dipartimento della Guerra e la stanza «Capogilda e Corrispondenti».\n\nTutto dentro la tua gilda.\n\nUna regola: pianificala, chiamala, e presentati.",
	RB_CORR_WAR_TITLE = "Corrispondente della Guerra",
	RB_COUNCIL = "Ok, ascolta.\n\nOra fai parte dell'Alto Consiglio. È enorme. Questo grado non si farma. Sei stato scelto. Non farcene pentire.\n\nIl compito: guidare Olympus con me. Giudicare, chiamare l'esercito, prenderti cura del posto.\n\nCosa si vede: le ali d'argento sul tuo ritratto e il drago d'argento prima del tuo nome in chat. Puoi aggiungere un'icona dopo di esso sotto Il mio profilo > Icone.\n\nCosa ottieni:\n- Decreti reali, Ispezioni delle tabarde, Chiamate alle armi e Adunate per tutto l'esercito.\n- La Guardia: le segnalazioni del consiglio e un voto su ogni Giudizio. L'ultima parola è mia.\n- Fino a 10 moderatori di Olympus tuoi.\n- Nominare Apostoli e aprire la classifica pubblica della Chiesa.\n- Nominare Legati per la gilda del Re, nel Trono.\n- La stanza dell'Alto Consiglio.\n\nUna regola: agisci per Olympus, non per la tua gilda.",
	RB_COUNCIL_ARTISANRY = "Sei a capo dell'Artigianato. Nella stanza del tuo dipartimento c'è il corrispondente dell'Artigianato di ogni gilda. Gli strumenti del dipartimento arriveranno più avanti.",
	RB_COUNCIL_BADGE = "Anche lo scudo del tuo dipartimento compare sul tuo ritratto.",
	RB_COUNCIL_CHURCHDEPT = "Sei a capo del dipartimento della Chiesa. Nella stanza del tuo dipartimento c'è il corrispondente della Chiesa di ogni gilda, e la classifica della scheda Chiesa è aperta per te.",
	RB_COUNCIL_HERALDRY = "Sei a capo dell'Araldica. Pubblichi l'Agenda del Re per tutto l'esercito. Nella stanza del tuo dipartimento c'è il corrispondente dell'Araldica di ogni gilda.",
	RB_COUNCIL_JUSTICE = "Siedi nel Consiglio di Giustizia. Lo presiedo io. Quando non ci sono, lo presiede un consigliere dell'Alto Consiglio. Nella stanza del tuo dipartimento c'è il corrispondente di Giustizia di ogni gilda.",
	RB_COUNCIL_TITLE = "L'Alto Consiglio",
	RB_COUNCIL_TREASURY = "Sei a capo della Tesoreria Federale. Nella stanza del tuo dipartimento ci sono il Tesoriere federale e il corrispondente della Tesoreria di ogni gilda.",
	RB_COUNCIL_WAR = "Sei a capo della Guerra. Nella Sala di guerra della tua gilda conti come ufficiale. Nella stanza del tuo dipartimento c'è il corrispondente della Guerra di ogni gilda.",
	RB_GM_ARTISANRY = "Corrispondente dell'Associazione dell'Artigianato",
