	RB_GM_CHARTER_TEXT = "Scopo, lingua, serate d'incursione e le classi che cerchi, pubblici per sette giorni. Aiuta le reclute a scegliere te.",
	RB_GM_CHURCH = "Corrispondente della Chiesa (la scheda Chiesa)",
