	RB_GM_CHURCHDEPT_JOB = "Il contatto della tua gilda per la Chiesa: porta dentro nuovi giocatori e aiuta a tenere piena la gilda.",
	RB_GM_CHURCHDEPT_SHOWS = "Lo scudo della Chiesa Missionaria sul suo ritratto e accanto al suo nome.",
	RB_GM_CHURCHDEPT_UNLOCKS = "Il titolo e la stanza del dipartimento. La stanza e i numeri della Chiesa vera e propria arrivano con la riga successiva.",
	RB_GM_CHURCH_JOB = "Risponde al Capo della Chiesa per tenere piena la tua gilda. Nomina la stessa persona della riga sopra.",
	RB_GM_CHURCH_SHOWS = "Niente sul ritratto.",
	RB_GM_CHURCH_UNLOCKS = "La stanza della Chiesa, i numeri della scheda Chiesa e la registrazione delle reclute che ha portato.",
	RB_GM_CLOSE = "Una regola: il tuo potere si ferma alla porta della tua gilda. Lì dentro, usalo bene.\n\nOra vai a costruire qualcosa. Andiamo!",
	RB_GM_DONE = "[x] %s",
	RB_GM_GET = "Cosa ottieni come capogilda:\n- Le ali di bronzo sul tuo ritratto e il segno di bronzo accanto al tuo nome.\n- La scheda Gilda: questa lista e la pagina di ogni dipartimento.\n- Chiamate alle armi, Adunate, decreti reali e Ispezioni delle tabarde per la tua gilda.\n- L'Agenda della tua gilda e i sondaggi di Vox Populi per la tua gilda.\n- La Guardia per la tua gilda, con i tuoi Capitani.\n- Le stanze «Capigilda», «Capigilda e Legati», «Capogilda e Legati» e «Capogilda e Corrispondenti».",
	RB_GM_HERALDRY = "Corrispondente del Dipartimento di Araldica",
	RB_GM_HERALDRY_JOB = "Gestisce i decreti, l'Agenda e le adunate della tua gilda, e fa sì che la gente si presenti.",
