	RB_GM_JOB = "Compito: %s",
	RB_GM_JUSTICE = "Corrispondente del Consiglio di Giustizia",
	RB_GM_JUSTICE_JOB = "Tiene pulita la chat della tua gilda e applica il mio giudizio quando confermo un caso.",
	RB_GM_JUSTICE_SHOWS = "Lo scudo del Consiglio di Giustizia sul suo ritratto e accanto al suo nome.",
	RB_GM_JUSTICE_UNLOCKS = "L'intero banco della Guardia per i membri della tua gilda sotto di lui. La stanza del Consiglio di Giustizia.",
	RB_GM_LEGATES = "Legati (%d su %d)",
	RB_GM_LEGATES_JOB = "Ognuno guida un gruppo d'incursione: lui e fino a 39 compagni di gilda che hanno accettato, 40 in tutto.",
	RB_GM_LEGATES_SHOWS = "Lo scudo del Legato sul suo ritratto, e lo stesso scudo accanto al suo nome.",
	RB_GM_LEGATES_UNLOCKS = "Il suo gruppo nella Sala di guerra (scheda Il Reame): assegnare e rimuovere soldati, inviti all'incursione, una chat privata della squadra. Le stanze «Capigilda e Legati».",
	RB_GM_MUST = "Nomina questi",
	RB_GM_OPEN = "Ok, ascolta.\n\nGuidi una gilda in Olympus. Non è cosa da poco. Olympus è l'esercito, ma la tua gilda è dove la gente vive davvero.\n\nNon puoi farcela da solo, e non dovresti. Nomina la tua gente. Ogni riga qui sotto si apre con un clic e si spunta da sola quando è fatta. Un titolo per persona, e solo membri della tua gilda.",
	RB_GM_PREVIEW = "(Nella lettera di un capogilda ogni riga si spunta da sola, e il suo pulsante apre il passaggio.)",
	RB_GM_SHOWS = "Si vede: %s",
	RB_GM_TITLE = "Capogilda: nomina la tua gente",
	RB_GM_TODO = "[  ] %s",
	RB_GM_TREASURY = "Corrispondente della Tesoreria Federale",
	RB_GM_TREASURY_JOB = "Tiene in ordine i registri della Tesoreria della tua gilda e la condivisione della banca, con te e con la Tesoreria Federale.",
	RB_GM_TREASURY_SHOWS = "Lo scudo della Tesoreria Federale sul suo ritratto e accanto al suo nome.",
	RB_GM_TREASURY_UNLOCKS = "Le scorte della banca della tua gilda e la sua pagina della Tesoreria. La stanza della Tesoreria Federale.",
	RB_GM_UNLOCKS = "Sblocca: %s",
	RB_GM_WAR = "Corrispondente del Dipartimento della Guerra",
	RB_GM_WAR_JOB = "Gestisce le incursioni e le operazioni PvP della tua gilda.",
	RB_GM_WAR_SHOWS = "Lo scudo del Dipartimento della Guerra sul suo ritratto e accanto al suo nome.",
	RB_GM_WAR_UNLOCKS = "Diritti da ufficiale nella tua Sala di guerra: operazioni, gruppi d'incursione, incarichi, resoconti post-azione. La stanza del Dipartimento della Guerra.",
	RB_GM_WATCHERS = "Membri della Guardia",
	RB_GM_WATCHERS_TEXT = "I tuoi Capitani hanno già la Guardia. La ricevono anche i membri della Guardia, per i tuoi membri sotto di loro.",
	RB_GM_WORTH = "Utili anche questi",
	RB_GUILD_TAB_LINK = "La tua lettera del Re: %d nominati su %d",
	RB_HAND = "Ok,\n\nTi ho nominato Mano del Re. Non è cosa da poco. Usi i miei strumenti, a nome mio.\n\nCosa si vede: nessuna nuova cornice. La scheda Trono si apre per te.\n\nCosa ottieni:\n- Convoca i Signori: un appello di ogni Signore e Capitano online.\n- Ispezione reale: l'esercito controlla le tabarde intorno a sé.\n- L'Agenda del Re e i sondaggi di Vox Populi.\n- Le porte: dove vanno le nuove reclute.\n- Chiamate alle armi e Adunate per tutto l'esercito.\n\nCosa resta mio: la lista delle Mani, i mandati, la corte e le grazie.\n\nUna regola: non spammare l'esercito. Ogni chiamata che mandi compare sullo schermo di tutti.",
	RB_HAND_TITLE = "Mano del Re",
	RB_HELP = "  /oly duties - rileggi le lettere del Re per le tue cariche",
	RB_KEEPER = "Ehi,\n\nTi ho nominato custode della tesoreria. Ti affido l'oro. Non fare cose strane.\n\nIl compito: tenere una parte della tesoreria sul tuo personaggio, accanto al Tesoriere.\n\nCosa si vede: nessuna nuova cornice.\n\nCosa ottieni:\n- Il tuo libro nella scheda Tesoreria. L'oro e gli oggetti che la gente ti dà per scambio o per posta contano come donazioni, da soli, una volta che accetti di condividerlo.\n- L'oro tra due custodi è un trasferimento, mai una donazione.\n- Quello che guadagni giocando resta tuo. Una vendita o un acquisto entra come non conteggiato.\n\nI custodi sono al massimo cinque, e posso revocarti in qualsiasi momento.\n\nUna regola: l'oro donato non è mai tuo da spendere.",
	RB_KEEPER_TITLE = "Custode della tesoreria",
	RB_LAUNCH = "Ok, ascoltate.\n\nLa beta è finita. Ci siamo. Olympus è live.\n\nNon molto tempo fa erano poche gilde e un'idea. Ora guardatelo. Un esercito, un reame, e dentro ci siete tutti voi. È enorme. Davvero.\n\nStavolta di nuovo c'è poco. Ogni carica ora riceve la sua lettera, e i capigilda trovano una checklist nella loro. Tutto qui. Il resto dipende da voi.\n\nUn'ultima cosa. Fern ci ha costruito una sala della gilda: olympus.roachcouncil.com. Se siete nel Discord, accedete e varcate le porte. Grazie, Fern. Sul serio.\n\nFate i bravi in chat. Aiutate i nuovi. Portate i vostri amici.\n\nBuon gioco. Lo dico sul serio. Andiamo!",
	RB_LAUNCH_TITLE = "Le porte sono aperte",
	RB_LEGATE = "Ok, ascolta.\n\nOra sei un Legato di <%s>. Andiamo!\n\nIl compito: guidare un gruppo d'incursione. Tu e fino a 39 compagni di gilda che hanno accettato, 40 in tutto. Portali a eventi, incursioni e guerre.\n\nCosa si vede: lo scudo del Legato sul tuo ritratto, e lo stesso scudo accanto al tuo nome.\n\nCosa ottieni:\n- Il tuo gruppo nella Sala di guerra (scheda Il Reame): assegnare e rimuovere soldati, invitare all'incursione quelli online, una chat privata della squadra.\n- Le stanze «Capigilda e Legati» nella Chat.\n\nNiente è automatico: nessun invito in gilda, espulsione o promozione. I gruppi sono facoltativi, e la gente può giocare con un altro capo.\n\nUna regola: metti in lista solo chi ha detto sì.",
	RB_LEGATE_TITLE = "Legato",
	RB_LINK = "Lettere d'incarico",
	RB_LINK_PREVIEW = "Lettere d'incarico (anteprima)",
	RB_MISSIONARY = "Ehi,\n\nOra sei un missionario della Chiesa, nella rete di %s. Benvenuto.\n\nIl compito: portare nuovi giocatori in Olympus.\n\nCosa si vede: i tre migliori missionari degli ultimi 30 giorni portano il bastone pastorale.\n\nCosa ottieni:\n- Invita nuovi giocatori nella tua gilda e l'addon lo conta da solo, una volta che l'addon di un altro giocatore lo conferma.\n- Hai portato qualcuno invitato da un altro giocatore? Registralo nella scheda Chiesa. Conta se entra in una gilda Olympus entro 14 giorni.\n- Fino a 12 missionari tuoi, a meno che tu non sia già cinque livelli sotto.\n- La scheda Chiesa, la stanza «Apostoli e missionari» e la stanza della Chiesa.\n\nPunti: 10 per ogni nuovo giocatore, altri 5 se resta 7 giorni.\n\nUna regola: solo veri giocatori nuovi. Alt e passaggi tra gilde Olympus non contano mai.",
	RB_MISSIONARY_TITLE = "Missionario",
	RB_MODERATOR = "Ok, ascolta.\n\nOra sei un moderatore di Olympus. Tieni pulite le chat di tutto l'esercito. È un lavoro vero.\n\nIl compito: occuparti di abusi, insulti, spam e truffe nelle chat di Olympus.\n\nCosa si vede: niente sul tuo ritratto.\n\nCosa ottieni:\n- La moderazione della chat della Guardia: cancellare righe e mettere in timeout le persone ovunque in Olympus, altri capigilda compresi. Mai il capogilda di <Olympus>, né nessuno sopra di te.\n- La stanza della Guardia, con l'Alto Consiglio, gli altri moderatori e me.\n\nResti moderatore finché chi ti ha nominato ti tiene nella sua lista.\n\nUna regola: quello che vedi nel team resta nel team.",
	RB_MODERATOR_TITLE = "Moderatore di Olympus",
	RB_NONE = "Ancora nessuna lettera per una carica di questo personaggio.",
	RB_NOT_LIVE = "Le lettere d'incarico non sono ancora uscite.",
	RB_PAGE_NOTE = "Una lettera del Re per ogni carica che questo personaggio ricopre, la prima volta che la ricopre. Restano qui, e sotto Il mio profilo > Lettere, da rileggere.",
	RB_PAGE_TITLE = "Lettere per le tue cariche",
	RB_PREVIEW_DEPT = "%s: %s",
	RB_PREVIEW_HEAD = "Anteprima: tutte le lettere d'incarico",
	RB_PREVIEW_LETTER = "Anteprima: niente viene salvato o inviato, e i pulsanti non fanno nulla.",
	RB_PREVIEW_NOTE = "Per l'autore e il Re: ogni lettera come la legge chi la riceve. Un'anteprima non salva nulla, non invia nulla e non segna nulla come letto, e i suoi pulsanti non fanno nulla.",
	RB_PREVIEW_OFF = "Non ancora uscite: nessuno riceve una lettera finché l'autore non le attiva.",
	RB_READY = "Ti attende una lettera del Re: %s. Aprila con /oly duties, oppure sotto Il mio profilo > Lettere.",
	RB_REALM_BACK = "< Torna al Reame",
	RB_SITE_TITLE = "Le porte di Olympus",
	RB_STEWARD = "Ehi,\n\nOra sei il mio Siniscalco. Vuol dire che quando non ci sono, tu sei me. Nessuna pressione.\n\nIl compito: mandare avanti il Trono a nome mio.\n\nCosa si vede: nessuna nuova cornice. Il tuo potere è nella scheda Trono.\n\nCosa ottieni:\n- Il Trono, agendo per il Re: appello, Ispezione reale, l'Agenda, Vox Populi, le porte.\n- Mani tue. Le nomini tu, le revochi tu.\n- Gli interruttori e i custodi della tesoreria, e l'importo delle quote settimanali.\n- Ogni tipo di decreto, per tutto l'esercito.\n- La stanza della Segreteria, con me.\n\nCosa resta mio: le mie Mani, la corte, i mandati e le grazie.\n\nUna regola: comportati come se ti stessi guardando. Perché lo farò.",
	RB_STEWARD_TITLE = "Il mio Siniscalco",
	RB_TREASURER = "Ehi,\n\nSei il Tesoriere federale. Custodisci l'oro di Olympus. Già. Tutto quanto.\n\nIl compito: tenere la tesoreria onesta, e in un solo libro.\n\nCosa si vede: la cornice del drago del Tesoriere sul tuo ritratto.\n\nCosa ottieni:\n- La scheda Tesoreria e il tuo libro: ogni scambio e ogni posta con oro o oggetti entra da solo, una volta che accetti di condividerlo.\n- Le quote settimanali, pagate a te. Chi ha pagato resta privato: lo vedono il Re e i Capitani di ogni gilda, mai l'esercito.\n- La stanza dell'Alto Consiglio e la stanza della Tesoreria Federale.\n\nQuello che guadagni giocando è tuo. Non entra mai nel libro.\n\nUna regola: ogni rame che entra, ogni rame che esce. Nel libro.",
	RB_TREASURER_TITLE = "Il Tesoriere federale",
	RB_WATCHER = "Ehi,\n\nIl tuo capogilda ti ha nominato membro della Guardia di <%s>. Aiuti a tenere pulita la chat.\n\nIl compito: tenere d'occhio la chat della tua gilda e intervenire quando qualcuno passa il limite.\n\nCosa si vede: niente sul tuo ritratto.\n\nCosa ottieni: l'intero banco della Guardia (scheda La Guardia) per i membri della tua gilda sotto di te: avvertimenti, timeout, la lista di sorveglianza, segnalazioni e casi.\n\nResti membro della Guardia finché il tuo capogilda ti tiene nella sua lista.\n\nUna regola: prima avverti. Poi i timeout salgono: un'ora, un giorno, una settimana.",
